-- 01 International Trade & Investment ---------------------------------------
INSERT OR IGNORE INTO programme_areas (id, slug, code, title, tagline, summary, description, image_url, status, sort_order) VALUES ('area-international-trade-investment', 'international-trade-investment', '01', 'International Trade & Investment', 'Trade, AfCFTA, investment and cross-border commerce', 'Develop the strategic knowledge and practical capability required to navigate cross-border commerce, African market integration, investment and international business.', 'Africa’s continental market is being built in real time. This area equips executives, trade professionals, investors and policymakers to work confidently across borders — from AfCFTA rules of origin and trade documentation to investment promotion, trade finance and international commercial negotiation.', 'https://images.unsplash.com/photo-1504274066651-8d31a536b11a?auto=format&fit=crop&w=1400&q=82', 'PUBLISHED', 1);
INSERT OR IGNORE INTO programmes (id, slug, area_id, type_id, title, subtitle, summary, description, image_url, level, duration_label, delivery_mode, certificate_award, eligibility, who_should_attend, learning_outcomes, tuition_amount, tuition_currency, cpd_points, featured, status, sort_order) VALUES ('prog-advanced-certificate-in-international-trade-and-investment', 'advanced-certificate-in-international-trade-and-investment', 'area-international-trade-investment', 'type-executive-certificate', 'Advanced Certificate in International Trade & Investment', 'Trade, AfCFTA, investment and cross-border commerce', 'An assessed executive certificate in international trade & investment, developed for senior professionals working in international trade & investment.', 'An assessed executive certificate in international trade & investment, developed for senior professionals working in international trade & investment. Delivered by WUCO Executive Academy as part of International Trade & Investment, and backed by the institutional authority of the World United Consumer Organisation.', 'https://images.unsplash.com/photo-1504274066651-8d31a536b11a?auto=format&fit=crop&w=1400&q=82', 'Advanced Executive', '12 weeks', 'Blended', 'WEA Advanced Executive Certificate', 'Open to professionals with relevant working experience. No formal academic prerequisite.', 'Senior managers, directors, regulators and professionals seeking a formal executive qualification.', '["Set direction in international trade & investment with confidence","Evaluate risk, regulation and commercial opportunity together","Lead change across teams, institutions and borders","Defend your decisions to a board, a regulator or a market"]', 1450, 'USD', 30, 1, 'PUBLISHED', 1);
