INSERT OR IGNORE INTO programme_modules (id, programme_id, number, title, summary, duration_label, sort_order) VALUES ('mod-advanced-certificate-in-international-trade-and-investment-2', 'prog-advanced-certificate-in-international-trade-and-investment', 2, 'Cross-border trade and trade facilitation', '', '3 weeks', 2);
