INSERT OR IGNORE INTO programme_areas (id, slug, code, title, tagline, summary, description, image_url, status, sort_order) VALUES ('area-banking-finance-financial-services', 'banking-finance-financial-services', '02', 'Banking, Finance & Financial Services', 'Banking leadership, regulation, risk and financial innovation', 'Build the judgement required to lead financial institutions through regulation, risk, digital transformation and rising consumer expectations.', 'Financial services sit at the centre of Africa’s economic transition. This area develops banking executives, regulators, risk professionals and fintech leaders across governance, compliance, financial crime, digital banking and the responsible use of artificial intelligence in credit and customer decisions.', 'https://images.unsplash.com/photo-1554224155-6726b3ff858f?auto=format&fit=crop&w=1400&q=82', 'PUBLISHED', 2);
