INSERT OR IGNORE INTO programme_areas (id, slug, code, title, tagline, summary, description, image_url, status, sort_order) VALUES ('area-retail-consumer-markets-customer-experience', 'retail-consumer-markets-customer-experience', '03', 'Retail, Consumer Markets & Customer Experience', 'Retail strategy, consumer intelligence and customer experience', 'Understand how African consumers behave, and build retail and service organisations that earn their trust and keep it.', 'Retail and consumer markets are where strategy meets everyday reality. This area covers retail leadership, omnichannel strategy, consumer intelligence, complaint and dispute handling, e-commerce and the operational discipline behind a genuinely good customer experience.', 'https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&w=1400&q=82', 'PUBLISHED', 3);
