INSERT OR IGNORE INTO programme_areas (id, slug, code, title, tagline, summary, description, image_url, status, sort_order) VALUES ('area-consumer-protection-consumer-intelligence', 'consumer-protection-consumer-intelligence', '04', 'Consumer Protection & Consumer Intelligence', 'A signature WEA area, backed by the World United Consumer Organisation', 'Build the regulatory literacy and analytical capability to protect consumers and to run a business that deserves their confidence.', 'Consumer protection is WEA’s signature discipline, reflecting the institutional mandate of the World United Consumer Organisation. This area addresses consumer rights, complaint and dispute systems, product safety, advertising standards, digital market conduct and the fast-moving question of consumer rights in an age of automated decisions.', 'https://images.unsplash.com/photo-1521737711867-e3b97375f902?auto=format&fit=crop&w=1400&q=82', 'PUBLISHED', 4);
