INSERT OR IGNORE INTO programme_areas (id, slug, code, title, tagline, summary, description, image_url, status, sort_order) VALUES ('area-artificial-intelligence-digital-transformation', 'artificial-intelligence-digital-transformation', '05', 'Artificial Intelligence, Digital Transformation & Responsible AI', 'AI strategy, governance and responsible adoption', 'Lead the adoption of artificial intelligence with judgement — capturing the advantage while governing the risk.', 'Artificial intelligence is reshaping how organisations decide, serve and compete. This area prepares executives, regulators and professionals to set AI strategy, govern AI risk, meet emerging regulatory expectations, and apply AI responsibly across banking, retail, trade, legal practice and public administration.', 'https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1400&q=82', 'PUBLISHED', 5);
