-- 06 Executive Short Case Series --------------------------------------------
INSERT OR IGNORE INTO programme_areas (id, slug, code, title, tagline, summary, description, image_url, status, sort_order) VALUES ('area-executive-short-case-series', 'executive-short-case-series', '06', 'Executive Short Case Series', 'Short, decision-centred cases from real African situations', 'Practise the decision itself. Each short case puts you inside a real situation with incomplete information and a deadline.', 'The Executive Short Case Series is a distinct WEA format: compact, intensive cases built around a single executive decision. Participants work through the situation, defend a position and compare it with how the decision was actually handled.', 'https://images.unsplash.com/photo-1526628953301-3e589a6a8b74?auto=format&fit=crop&w=1400&q=82', 'PUBLISHED', 6);
INSERT OR IGNORE INTO programmes (id, slug, area_id, type_id, title, subtitle, summary, description, image_url, level, duration_label, delivery_mode, certificate_award, eligibility, who_should_attend, learning_outcomes, tuition_amount, tuition_currency, cpd_points, featured, status, sort_order) VALUES ('prog-a-nigerian-retailer-faces-a-consumer-data-crisis', 'a-nigerian-retailer-faces-a-consumer-data-crisis', 'area-executive-short-case-series', 'type-executive-short-case', 'A Nigerian Retailer Faces a Consumer Data Crisis', 'Short, decision-centred cases from real African situations', 'A short, decision-centred case: a nigerian retailer faces a consumer data crisis. Work the situation, commit to a decision, then compare it with what actually happened.', 'A short, decision-centred case: a nigerian retailer faces a consumer data crisis. Work the situation, commit to a decision, then compare it with what actually happened. Delivered by WUCO Executive Academy as part of Executive Short Case Series, and backed by the institutional authority of the World United Consumer Organisation.', 'https://images.unsplash.com/photo-1526628953301-3e589a6a8b74?auto=format&fit=crop&w=1400&q=82', 'Executive', '90 minutes', 'Online', 'WEA Executive Short Case Record', 'Open to professionals with relevant working experience. No formal academic prerequisite.', 'Executives and managers who want decision practice rather than another lecture.', '["Read a live situation quickly and identify what is actually being decided","Weigh commercial, regulatory and reputational consequences together","Commit to a defensible decision under incomplete information"]', 95, 'USD', 2, 0, 'PUBLISHED', 1);
